function renderStack(){$('stackName').textContent=state.stack;$('confidence').textContent='Heuristic confidence '+state.confidence+'%';$('stackEvidence').innerHTML=state.evidence.slice(0,12).map(e=>`<span class="badge" title="${escapeHtml(e.stack)}">${escapeHtml(e.why)}</span>`).join('')||'<span class="subtle text-xs">No indicators</span>';$('libraries').textContent=state.libraries.length?'Other libraries: '+state.libraries.join(' · '):'No additional library fingerprints identified.';renderExports();}
function serverCaptureEnabled(){return !!$('serverCapture')?.checked&&typeof location!=='undefined'&&location.protocol==='https:'&&location.hostname.endsWith('.vercel.app');}
function assetAllowed(url){return sameOrigin(url)||serverCaptureEnabled();}
async function serverResource(url,signal){const token=$('captureToken').value;if(!token)throw Error('Enter the configured capture token or use browser capture / Import ZIP.');const r=await fetch('/api/capture',{method:'POST',signal,credentials:'omit',headers:{'content-type':'application/json','x-audit-token':token},body:JSON.stringify({url})});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:'Server capture HTTP '+r.status);const raw=atob(data.base64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return {bytes,headers:new Headers({'content-type':data.contentType}),type:data.contentType,url:data.url};}
