async function getRobots(signal){try{const r=await fetchText(state.origin+'/robots.txt',signal);const groups=[];let agents=[],rules=[];const flush=()=>{if(agents.length)groups.push({agents,rules});agents=[];rules=[];};for(const raw of r.text.split(/\r?\n/)){const line=raw.replace(/#.*$/,'').trim(),m=line.match(/^([\w-]+):\s*(.*)$/);if(!m){if(!line)flush();continue;}const key=m[1].toLowerCase(),val=m[2].trim();if(key==='sitemap'){const u=normalize(val);if(u&&sameOrigin(u))state.sitemaps.push(u);continue;}if(key==='user-agent'){if(rules.length)flush();agents.push(val.toLowerCase());}else if((key==='allow'||key==='disallow')&&agents.length&&val)rules.push({type:key,path:val});}flush();state.robots=groups.filter(g=>g.agents.includes('*')).flatMap(g=>g.rules);state.evidence.push({stack:'Robots',why:`robots.txt checked (${state.robots.length} wildcard rules)`});}catch(e){if(e.name==='AbortError'||serverCaptureEnabled())throw e;flash('robots.txt unavailable (possibly CORS); proceeding with caution. Crawl only sites you are permitted to inspect.',true);}} 
